[
  {
    "statement": "Several conservation actions show effectiveness for increasing butterfly populations on farmland.",
    "citations": []
  },
  {
    "statement": "Paying farmers to cover costs of conservation measures through agri-environment schemes shows consistent benefits for butterflies.",
    "citations": [
      "3915"
    ]
  },
  {
    "statement": "Farmland managed under agri-environment schemes has been found to have higher butterfly abundance compared to conventional fields.",
    "citations": [
