    ]
  },
  {
    "statement": "Farmland managed under agri-environment schemes has been found to have greater butterfly species richness compared to conventional fields.",
    "citations": [
      "3915"
    ]
  },
  {
    "statement": "Leaving headlands in fields unsprayed can result in greater butterfly abundance compared to sprayed headlands.",
    "citations": [
      "3898"
    ]
  },
  {
