    "citations": [
      "3981"
    ]
  },
  {
    "statement": "Agri-environment schemes that pay farmers for conservation measures may be among the most cost-effective approaches for butterfly conservation.",
    "citations": []
  },
  {
    "statement": "Agri-environment schemes can be cost-effective because the schemes can incorporate multiple beneficial practices simultaneously.",
    "citations": []
  }
