[
  {
    "statement": "There is limited research specifically on specialist herbivorous insects for biological control of invasive plants affecting butterfly habitats.",
    "citations": []
  },
  {
    "statement": "A controlled, replicated field study in China found that a flea beetle caused heavy feeding destruction when added to field cages containing prostrate water primrose seedlings.",
    "citations": [
      "1135"
    ]
  },
  {
    "statement": "The flea beetle in the Chinese field study was specific to the prostrate water primrose and Indian toothcup.",
    "citations": [
      "1135"
    ]
  },
  {
    "statement": "A replicated, before-and-after field study in the USA found that the introduction of flea beetles to a pond significantly reduced the abundance of large-flower primrose-willow.",
    "citations": [
      "1135"
    ]
  },
  {
    "statement": "One field study in South Africa reported reduced growth of parrot's feather following the release of a South American leaf-feeding Lysathia.",
    "citations": [
      "1599"
    ]
  },
  {
    "statement": "No evidence was found for biological control using herbivores for the invasive species Crassula helmsii.",
    "citations": [
      "1277"
    ]
  },
  {
    "statement": "No evidence was found for using native herbivores for water primrose control.",
    "citations": [
      "1136"
    ]
  },
  {
    "statement": "No evidence was found for using native herbivores for floating pennywort control.",
    "citations": [
      "1124"
    ]
  },
  {
    "statement": "No evidence was found for using co-evolved herbivores for skunk cabbage control.",
    "citations": [
      "1098"
    ]
  },
  {
    "statement": "General removal or control of non-native or problematic plants has shown positive effects for butterflies.",
    "citations": [
      "3890"
    ]
  },
  {
    "statement": "Nine studies showed that sites where invasive plants were removed had greater species richness and abundance of butterflies compared to untreated sites.",
    "citations": [
      "3890"
    ]
  }
]

[
  {
    "statement": "No specific action is explicitly identified as the most cost-effective for butterfly and moth conservation.",
    "citations": []
  },
  {
    "statement": "Several actions show evidence of effectiveness for butterfly and moth conservation with varying resource implications.",
    "citations": []
  },
  {
    "statement": "Paying farmers to cover conservation costs through agri-environment schemes has the most substantial evidence base, with 32 studies evaluating its effects.",
    "citations": [
      "3915"
    ]
  },
  {
    "statement": "Seventeen of 19 studies found a higher abundance of butterflies and moths on farms managed under agri-environment schemes compared to conventional farms.",
    "citations": [
      "3915"
    ]
  },
  {
    "statement": "Twelve of 15 studies found higher species richness or diversity of butterflies and moths on farms managed under agri-environment schemes compared to conventional farms.",
    "citations": [
      "3915"
    ]
  },
  {
    "statement": "Paying farmers through agri-environment schemes involves direct financial costs but demonstrates consistent positive outcomes.",
    "citations": [
      "3915"
    ]
  },
  {
    "statement": "Reducing the general use of fertilizer, pesticide or herbicide showed effectiveness in 11 studies.",
    "citations": [
      "3897"
    ]
  },
  {
    "statement": "Eight studies found greater species richness in areas with reduced chemical inputs compared to conventional applications.",
    "citations": [
      "3897"
    ]
  },
  {
    "statement": "Six studies found a higher abundance of butterflies and moths with reduced chemical use.",
    "citations": [
      "3897"
    ]
  },
  {
    "statement": "Reducing fertilizer, pesticide or herbicide use may offer cost savings through reduced input purchases while providing conservation benefits.",
    "citations": [
      "3897"
    ]
  },
  {
    "statement": "Providing training for land managers, farmers and farm advisers showed promising results in one UK study.",
    "citations": [
      "3846"
    ]
  },
  {
    "statement": "In one UK study, 82% of landowners receiving advice submitted agri-environment scheme applications with a 90% success rate.",
    "citations": [
      "3846"
    ]
  },
  {
    "statement": "The successful applications from trained landowners resulted in the management of over 3,000 hectares for marsh fritillary conservation.",
    "citations": [
      "3846"
    ]
  },
  {
    "statement": "Several other actions had limited evidence, with studies finding no evaluations for increasing consideration of butterflies and moths in conservation plans or for legal protection.",
    "citations": [
      "3848",
      "3863"
    ]
  },
  {
    "statement": "Habitat management actions like managing woodland edges and restoring grassland showed positive effects but with limited study numbers to assess cost-effectiveness.",
    "citations": [
      "3942",
      "3955"
    ]
  }
]

[
  {
    "statement": "No studies have been found that directly evaluated the effects of using signs and access restrictions to reduce disturbance on butterflies and moths.",
    "citations": [
      "3849"
    ]
  },
  {
    "statement": "A systematic review found no evidence for the intervention of using signs and access restrictions specifically for lepidoptera conservation.",
    "citations": []
  },
  {
    "statement": "The absence of studies means that the effectiveness of signs and access restrictions for reducing disturbance to butterfly and moth populations cannot be assessed based on current research evidence.",
    "citations": []
  }
]

[
  {
    "statement": "No studies were found that specifically evaluated the effects of microplastic pollution on butterfly and moth populations.",
    "citations": []
  },
  {
    "statement": "The action documents searched included interventions related to biodegradable fishing gear, pollution reduction measures, and butterfly and moth conservation planning.",
    "citations": [
      "2885",
      "3565",
      "2201",
      "3848"
    ]
  },
  {
    "statement": "None of the searched action documents contained research or evidence directly addressing microplastic pollution impacts on butterflies and moths.",
    "citations": [
      "2885",
      "3565",
      "2201",
      "3848"
    ]
  },
  {
    "statement": "The absence of studies on microplastic pollution's effects on butterflies and moths in the action database indicates that this specific area of research may not yet have been systematically evaluated.",
    "citations": []
  },
  {
    "statement": "The specific area of research on microplastic pollution's effects on butterflies and moths may not yet have been documented in the conservation literature reviewed.",
    "citations": []
  }
]

[
  {
    "statement": "Planting parks, gardens and road verges with appropriate native species appears to be the most important conservation action for monarch butterflies.",
    "citations": [
      "3842"
    ]
  },
  {
    "statement": "When taller native milkweed species were planted, the taller species had a higher abundance of monarch butterfly eggs and caterpillars than shorter milkweed species.",
    "citations": [
      "3842"
    ]
  },
  {
    "statement": "Monarch butterfly adults used common milkweed planted in gardens more than milkweed planted in meadows.",
    "citations": [
      "3842"
    ]
  },
  {
    "statement": "The survival of monarch butterfly caterpillars was similar on common milkweed planted in gardens and meadows.",
    "citations": [
      "3842"
    ]
  },
  {
    "statement": "The growth of monarch butterfly caterpillars was similar on eight different native milkweed species.",
    "citations": [
      "3842"
    ]
  },
  {
    "statement": "Common milkweed planted in meadows supported monarch butterfly eggs.",
    "citations": [
      "3933"
    ]
  },
  {
    "statement": "The survival rates for monarch butterfly eggs and caterpillars were similar in meadows or private gardens.",
